return [
  {
    json: {
      project_name: $json["Project Name"] || "",
      product_name: $json["Product Name"] || "",
      product_type: $json["Product Type"] || "",
      requirements: $json["PRD / Requirements"] || "",
      user_roles: $json["User Roles"] || "",
      features: $json["Features"] || "",
      platform: $json["Platform"] || "",
      priority: $json["Priority"] || "",
      environment: $json["Environment"] || "",
      submitted_at: new Date().toISOString()
    }
  }
];

const raw = $input.first().json.output;

let report;

try {
  // Remove markdown code fences if the AI added them
  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // Extract the JSON object if extra text exists
  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error("No valid JSON object found in AI output");
  }

  cleaned = cleaned.substring(start, end + 1);

  report = JSON.parse(cleaned);

} catch (error) {
  return [
    {
      json: {
        report_type: "AI QA Test Report",
        parse_status: "failed",
        error: error.message,
        raw_output: raw
      }
    }
  ];
}

// Return clean structured fields
return [
  {
    json: {
      report_type: "AI QA Test Report",

      project_summary:
        report.project_summary ?? "TBD",

      testing_scope:
        report.testing_scope ?? "TBD",

      requirements_summary:
        report.requirements_summary ?? "TBD",

      test_scenario_summary:
        report.test_scenario_summary ?? "TBD",

      test_case_summary:
        report.test_case_summary ?? "TBD",

      positive_test_cases:
        report.positive_test_cases ?? [],

      negative_test_cases:
        report.negative_test_cases ?? [],

      edge_cases:
        report.edge_cases ?? [],

      security_test_cases:
        report.security_test_cases ?? [],

      integration_test_cases:
        report.integration_test_cases ?? [],

      compatibility_test_cases:
        report.compatibility_test_cases ?? [],

      coverage_assessment:
        report.coverage_assessment ?? {},

      uncovered_requirements:
        report.uncovered_requirements ?? [],

      partially_covered_requirements:
        report.partially_covered_requirements ?? [],

      high_risk_gaps:
        report.high_risk_gaps ?? [],

      recommendations:
        report.recommendations ?? [],

      traceability_summary:
        report.traceability_summary ?? {},

      qa_readiness:
        report.qa_readiness ?? "TBD",

      final_assessment:
        report.final_assessment ?? "TBD",

      parse_status: "success"
    }
  }
];
